<?php
declare(strict_types=1);
$isHttps=isset($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!==''&&$_SERVER['HTTPS']!=='off';ini_set('session.use_strict_mode','1');session_name('coaching_tool_session');session_set_cookie_params(['httponly'=>true,'secure'=>$isHttps,'samesite'=>'Strict','path'=>'/']);session_start();header('Cache-Control: no-store, private');
require_once dirname(__DIR__).'/app/bootstrap.php';require_once dirname(__DIR__).'/app/navigation.php';
function roomCalendarH(string|int|null $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
$user=$_SESSION['user']??null;if(!is_array($user)||!isset($user['id'],$user['role'])||!in_array($user['role'],['admin','coach'],true)){http_response_code(403);exit('Der Raumkalender steht Coaches und Administratoren zur Verfügung.');}
$db=coachingDatabase();$role=(string)$user['role'];$coachId=(int)$user['id'];$token=$_SESSION['csrf_token']??'';if(!is_string($token)||strlen($token)!==64){$token=bin2hex(random_bytes(32));$_SESSION['csrf_token']=$token;}
$error='';$notice=isset($_GET['saved'])?'Die Raumbuchung wurde gespeichert.':(isset($_GET['cancelled'])?'Die Buchung wurde storniert.':'');
if($_SERVER['REQUEST_METHOD']==='POST'){
 $posted=$_POST['csrf_token']??'';$action=(string)($_POST['action']??'');
 if(!is_string($posted)||!hash_equals($token,$posted))$error='Die Anfrage ist abgelaufen. Bitte lade die Seite neu.';
 else try{
  if($action==='book'&&$role==='coach'){
   $roomId=filter_var($_POST['raum_id']??null,FILTER_VALIDATE_INT);$roomId=$roomId===false?0:(int)$roomId;
   $title=trim(is_string($_POST['titel']??null)?$_POST['titel']:'');$note=trim(is_string($_POST['notiz']??null)?$_POST['notiz']:'');$startRaw=is_string($_POST['beginn']??null)?$_POST['beginn']:'';$endRaw=is_string($_POST['ende']??null)?$_POST['ende']:'';
   $zone=new DateTimeZone('Europe/Berlin');$start=DateTimeImmutable::createFromFormat('!Y-m-d\TH:i',$startRaw,$zone);$end=DateTimeImmutable::createFromFormat('!Y-m-d\TH:i',$endRaw,$zone);
   if(!$start||!$end||$start->format('Y-m-d\TH:i')!==$startRaw||$end->format('Y-m-d\TH:i')!==$endRaw||$start<new DateTimeImmutable('now',$zone)||$end<=$start||($end->getTimestamp()-$start->getTimestamp())>43200)throw new InvalidArgumentException('Bitte prüfe Raum, Titel sowie Anfang und Ende. Buchungen dürfen höchstens 12 Stunden dauern.');
   if($roomId<1||$title===''||strlen($title)>190||strlen($note)>1000)throw new InvalidArgumentException('Bitte gib einen gültigen Raum und Buchungstitel an.');
   $db->beginTransaction();$lock=$db->prepare('SELECT r.id FROM coaching_raeume r INNER JOIN coaching_raum_berechtigungen p ON p.raum_id=r.id AND p.coach_benutzer_id=:coach AND p.darf_buchen=1 WHERE r.id=:room AND r.aktiv=1 FOR UPDATE');$lock->execute(['coach'=>$coachId,'room'=>$roomId]);if(!$lock->fetchColumn())throw new InvalidArgumentException('Du hast keine Buchungsberechtigung für diesen Raum.');
   $collision=$db->prepare("SELECT id FROM coaching_raum_buchungen WHERE raum_id=:room AND status='gebucht' AND beginn<:end_at AND ende>:start_at LIMIT 1 FOR UPDATE");$collision->execute(['room'=>$roomId,'end_at'=>$end->format('Y-m-d H:i:s'),'start_at'=>$start->format('Y-m-d H:i:s')]);if($collision->fetchColumn())throw new InvalidArgumentException('Der Raum ist in diesem Zeitraum bereits gebucht.');
   $save=$db->prepare("INSERT INTO coaching_raum_buchungen (raum_id,coach_benutzer_id,titel,beginn,ende,notiz,status) VALUES (:room,:coach,:title,:start_at,:end_at,:note,'gebucht')");$save->execute(['room'=>$roomId,'coach'=>$coachId,'title'=>$title,'start_at'=>$start->format('Y-m-d H:i:s'),'end_at'=>$end->format('Y-m-d H:i:s'),'note'=>$note?:null]);$db->commit();header('Location: room-calendar.php?saved=1&week='.rawurlencode($start->format('Y-m-d')));exit;
  }elseif($action==='cancel'){
   $id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);$id=$id===false?0:(int)$id;if($id<1)throw new InvalidArgumentException('Ungültige Buchungsnummer.');
   if($role==='admin')$q=$db->prepare("UPDATE coaching_raum_buchungen SET status='storniert' WHERE id=:id AND status='gebucht'");
   else $q=$db->prepare("UPDATE coaching_raum_buchungen SET status='storniert' WHERE id=:id AND coach_benutzer_id=:coach AND status='gebucht'");
   $params=['id'=>$id];if($role==='coach')$params['coach']=$coachId;$q->execute($params);if($q->rowCount()!==1)throw new InvalidArgumentException('Die Buchung wurde nicht gefunden oder kann nicht storniert werden.');
   header('Location: room-calendar.php?cancelled=1');exit;
  }else throw new InvalidArgumentException('Unbekannte Aktion.');
 }catch(Throwable $e){if($db->inTransaction())$db->rollBack();if($e instanceof InvalidArgumentException)$error=$e->getMessage();else{error_log('Coaching Tool room booking failed: '.$e->getMessage());$error='Die Buchung konnte nicht gespeichert werden. Prüfe Migration 022 und Tabellenrechte.';}}
}
$zone=new DateTimeZone('Europe/Berlin');$weekRaw=is_string($_GET['week']??null)?$_GET['week']:'';$selected=DateTimeImmutable::createFromFormat('!Y-m-d',$weekRaw,$zone);if(!$selected)$selected=new DateTimeImmutable('today',$zone);$weekStart=$selected->modify('monday this week')->setTime(0,0);$weekEnd=$weekStart->modify('+7 days');$prev=$weekStart->modify('-7 days')->format('Y-m-d');$next=$weekStart->modify('+7 days')->format('Y-m-d');
$rooms=$role==='coach'?$db->prepare('SELECT r.id,r.name,r.standort FROM coaching_raeume r INNER JOIN coaching_raum_berechtigungen p ON p.raum_id=r.id WHERE p.coach_benutzer_id=:coach AND p.darf_buchen=1 AND r.aktiv=1 ORDER BY r.name'):null;if($rooms){$rooms->execute(['coach'=>$coachId]);$rooms=$rooms->fetchAll(PDO::FETCH_ASSOC);}else{$rooms=$db->query('SELECT id,name,standort FROM coaching_raeume WHERE aktiv=1 ORDER BY name')->fetchAll(PDO::FETCH_ASSOC);}
if($role==='admin'){$q=$db->prepare("SELECT b.id,b.raum_id,r.name AS raum,r.standort,b.beginn,b.ende,'Belegt' AS titel,NULL AS coach_benutzer_id FROM coaching_raum_buchungen b INNER JOIN coaching_raeume r ON r.id=b.raum_id WHERE b.status='gebucht' AND b.beginn>=:start_at AND b.beginn<:end_at ORDER BY b.beginn,r.name");$q->execute(['start_at'=>$weekStart->format('Y-m-d H:i:s'),'end_at'=>$weekEnd->format('Y-m-d H:i:s')]);}
else{$q=$db->prepare("SELECT b.id,b.raum_id,r.name AS raum,r.standort,b.beginn,b.ende,CASE WHEN b.coach_benutzer_id=:own_id THEN b.titel ELSE 'Belegt' END AS titel,b.coach_benutzer_id FROM coaching_raum_buchungen b INNER JOIN coaching_raeume r ON r.id=b.raum_id INNER JOIN coaching_raum_berechtigungen p ON p.raum_id=r.id AND p.coach_benutzer_id=:viewer AND p.darf_buchen=1 WHERE b.status='gebucht' AND b.beginn>=:start_at AND b.beginn<:end_at ORDER BY b.beginn,r.name");$q->execute(['own_id'=>$coachId,'viewer'=>$coachId,'start_at'=>$weekStart->format('Y-m-d H:i:s'),'end_at'=>$weekEnd->format('Y-m-d H:i:s')]);}
$bookings=$q->fetchAll(PDO::FETCH_ASSOC);$csrf=$token;
?>
<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Raumkalender · Coaching Tool</title><link rel="stylesheet" href="assets/layout.css"><script src="assets/layout.js" defer></script><style>.page{max-width:1150px;margin:auto;padding:32px clamp(20px,4vw,56px) 64px}.grid{display:grid;grid-template-columns:minmax(280px,360px) 1fr;gap:18px}.card{background:#fff;border:1px solid #e3ebe5;border-radius:14px;padding:20px;margin:18px 0}.form{display:grid;gap:10px}.form input,.form select,.form textarea{padding:11px;border:1px solid #dce5df;border-radius:8px;font:inherit}.button{border:0;border-radius:8px;padding:10px 14px;background:#245c50;color:#fff;font:inherit;cursor:pointer}.secondary{background:#edf5ef;color:#245c50}.row{display:grid;grid-template-columns:160px minmax(100px,1fr) 130px;gap:12px;padding:13px 0;border-bottom:1px solid #edf1ee;align-items:center}.notice,.error{padding:12px;border-radius:8px}.notice{background:#edf5ef}.error{background:#fff3f1;color:#842f2f}.muted{color:#718078;font-size:13px}.week{display:flex;justify-content:space-between;align-items:center;gap:12px}.mobile{display:none}@media(max-width:780px){.grid{grid-template-columns:1fr}.row{grid-template-columns:1fr;gap:4px}.mobile{display:inline}}</style></head><body class="has-app-sidebar"><?php renderCoachingSidebar($user,'room-calendar',$csrf);?><main class="page"><h1>Raumkalender</h1><p>Coaches sehen ihre Buchungen und freie Zeiten ihrer freigegebenen Räume. Administratoren sehen ausschließlich Belegungszeiten, ohne Buchungstitel oder Klientenbezug.</p><?php if($notice):?><p class="notice" role="status"><?=roomCalendarH($notice)?></p><?php endif;?><?php if($error):?><p class="error" role="alert"><?=roomCalendarH($error)?></p><?php endif;?><div class="grid"><?php if($role==='coach'):?><section class="card"><h2>Raum buchen</h2><?php if(!$rooms):?><p>Dir ist noch kein Raum zur Buchung freigegeben. Bitte wende dich an die Verwaltung.</p><?php else:?><form method="post" class="form"><input type="hidden" name="csrf_token" value="<?=roomCalendarH($csrf)?>"><input type="hidden" name="action" value="book"><label>Raum<select name="raum_id" required><?php foreach($rooms as $room):?><option value="<?=(int)$room['id']?>"><?=roomCalendarH($room['name'])?><?=!empty($room['standort'])?' · '.roomCalendarH($room['standort']):''?></option><?php endforeach;?></select></label><label>Titel<input name="titel" maxlength="190" required placeholder="z. B. Coaching-Sitzung"></label><label>Beginn<input name="beginn" type="datetime-local" required></label><label>Ende<input name="ende" type="datetime-local" required></label><label>Interne Notiz (optional)<textarea name="notiz" maxlength="1000" rows="3"></textarea></label><button class="button" type="submit">Raum verbindlich buchen</button></form><?php endif;?></section><?php else:?><section class="card"><h2>Raumübersicht</h2><p>Du kannst Räume anlegen und Buchungsrechte in Einstellungen → Räume verwalten einstellen. Der Kalender enthält keine Klientennamen oder Sitzungsinhalte.</p><a class="button" href="room-settings.php">Räume verwalten</a></section><?php endif;?><section class="card"><div class="week"><a class="button secondary" href="room-calendar.php?week=<?=roomCalendarH($prev)?>">‹ Vorige Woche</a><strong><?=roomCalendarH($weekStart->format('d.m.Y'))?> – <?=roomCalendarH($weekEnd->modify('-1 day')->format('d.m.Y'))?></strong><a class="button secondary" href="room-calendar.php?week=<?=roomCalendarH($next)?>">Nächste Woche ›</a></div><h2>Belegungsplan</h2><?php if(!$bookings):?><p>Für diese Woche sind keine Buchungen vorhanden.</p><?php else:foreach($bookings as $booking):$mine=$role==='coach'&&(int)$booking['coach_benutzer_id']===$coachId;?><article class="row"><div><strong><?=roomCalendarH(date('D, d.m.',strtotime($booking['beginn'])))?></strong><div><?=roomCalendarH(date('H:i',strtotime($booking['beginn'])))?>–<?=roomCalendarH(date('H:i',strtotime($booking['ende'])))?></div></div><div><strong><?=roomCalendarH($booking['raum'])?></strong><?=!empty($booking['standort'])?'<div class="muted">'.roomCalendarH($booking['standort']).'</div>':''?><div><?=roomCalendarH($booking['titel'])?></div></div><?php if($mine||$role==='admin'):?><form method="post" onsubmit="return confirm('Diese Raumreservierung stornieren?');"><input type="hidden" name="csrf_token" value="<?=roomCalendarH($csrf)?>"><input type="hidden" name="action" value="cancel"><input type="hidden" name="id" value="<?=(int)$booking['id']?>"><button class="button secondary" type="submit"><?=$role==='admin'?'Stornieren':'Eigene Buchung stornieren'?></button></form><?php endif;?></article><?php endforeach;endif;?></section></div></main></body></html>